			has_situation_flag = shroud_forged_560_positive_2
		}
		modifier = {
			add = @ShroudForgedNegative1
			desc = shroud_forged_560_negative_2_desc
			has_situation_flag = shroud_forged_560_negative_2
		}

		# Vibrations and Sounds
		modifier = {
			add = @ShroudForgedNegative1
			desc = shroud_forged_570_negative_1_desc
			has_situation_flag = shroud_forged_570_negative_1
		}
		modifier = {
			add = @ShroudForgedPositive1
			desc = shroud_forged_570_positive_1_desc
			has_situation_flag = shroud_forged_570_positive_1
		}

		# Shroud Flora
		modifier = {
