		modifier = {
			add = @ShroudForgedPositive1
			desc = shroud_forged_600_positive_2_desc
			has_situation_flag = shroud_forged_600_positive_2
		}
		modifier = {
			add = @ShroudForgedNegative1
			desc = shroud_forged_600_negative_2_desc
			has_situation_flag = shroud_forged_600_negative_2
		}

		# Individualistic Tendrils
		modifier = {
			add = @ShroudForgedPositive1
			desc = shroud_forged_610_positive_1_desc
			has_situation_flag = shroud_forged_610_positive_1
		}
		modifier = {
			add = @ShroudForgedNegative1
			desc = shroud_forged_610_negative_1_desc
