		}

		# Shroud Malady
		modifier = {
			add = @ShroudForgedPositive2
			desc = shroud_forged_630_positive_2_desc
			has_situation_flag = shroud_forged_630_positive_2
		}
		modifier = {
			add = @ShroudForgedNegative1
			desc = shroud_forged_630_negative_1_desc
			has_situation_flag = shroud_forged_630_negative_1
		}

		# Warped and Reshaped
		modifier = {
			add = @ShroudForgedPositive1
			desc = shroud_forged_640_positive_1_desc
			has_situation_flag = shroud_forged_640_positive_1
		}

		# New Technology, Old Drones
		modifier = {
			add = @ShroudForgedPositive1
			desc = shroud_forged_650_positive_1_desc
			has_situation_flag = shroud_forged_650_positive_1
		}
		modifier = {
			add = @ShroudForgedNegative1
			desc = shroud_forged_650_negative_1_desc
