			desc = progress_shroud_forged_suppress
			current_situation_approach = approach_shroud_forged_suppress
		}

		# Appease Approach
		modifier = {
			factor = 0.5
			desc = progress_shroud_forged_appease_halved
			current_situation_approach = approach_shroud_forged_appease
